import React, { createContext, useContext, useState, useEffect } from "react";
import { loginService, logoutService, verifyTwoFactorLoginService } from "../Services/authService";
import KeycloakService from "../Services/keycloakService";
import { useLocation, useNavigate } from "react-router-dom";
import { isTokenExpired, parseBoolean } from "../Services/globalServiceUtils";
import { department_admin_permissions, staff_admin_permissions } from "../Data/DefaultPermissions";
import { setUserTimezone, setShouldHidePrices as setShouldHidePricesGlobal } from "../Utilities/globalConfig";
import { fetchAgentServiceByStaffId } from "../Services/agentService";
import { isEnableKeycloak } from "../Utilities/keycloakUtils";
import { redirectToLogin } from "../Utilities/authRedirects";

// Create the context
const AuthContext = createContext();
const DEFAULT_LANDING_PAGE_PREFERENCES = {
	service_engineer_landing_page: "dashboard",
	service_manager_landing_page: "dashboard",
	customer_user_landing_page: "dashboard",
};

// Provider component
export const AuthProvider = ({ children }) => {
	const [user, setUser] = useState(null);
	const [userId, setUserId] = useState(null);
	const [userName, setUserName] = useState(null);
	const [userMode, setUserMode] = useState(null);
	const [userDepartments, setUserDepartments] = useState(null);
	const [userRole, setUserRole] = useState("");
	const [userPermissions, setUserPermissions] = useState(null);
	const [userAccount, setUserAccount] = useState(null);
	const [userToken, setUserToken] = useState(null);
// [...] (AuthContext.js truncated — 628 lines total)
	const [userAdditionalData, setUserAdditionalData] = useState(null);
	const [authMethod, setAuthMethod] = useState("local");
	const [isAdmin, setIsAdmin] = useState(false);
	const [isAgent, setIsAgent] = useState(true);
	const [isServiceManager, setIsServiceManager] = useState(false);
	const [isAuthenticated, setIsAuthenticated] = useState(false);
	const [loginUserTimezone, setLoginUserTimezone] = useState("system_default");
	const [shouldHidePrices, setShouldHidePrices] = useState(false);
	const [landingPagePreferences, setLandingPagePreferences] = useState(DEFAULT_LANDING_PAGE_PREFERENCES);

	const [loading, setLoading] = useState(true);
	const [authHydrated, setAuthHydrated] = useState(false);

	const navigate = useNavigate();
	const location = useLocation();

	// Function to check Keycloak session and validate user
	const checkKeycloakSession = async () => {
		// If Keycloak is disabled, skip the session check
		if (!isEnableKeycloak()) {
			return true;
		}

		try {
			console.log("AuthContext: Checking Keycloak session");
			const authenticated = await KeycloakService.initKeycloak(logout);

			if (!authenticated) {
				console.log("AuthContext: Keycloak session not active, logging out");
				// Clear auth state
				localStorage.removeItem("auth");
				setUser(null);
				setUserAccount(null);
				setUserToken(null);
				setUserMode(null);
				setUserId(null);
				setUserRole(null);
				setUserAdditionalData(null);
				setUserPermissions(null);
				setIsAdmin(false);
				setIsAgent(false);
				setIsServiceManager(false);
				setIsAuthenticated(false);
				setUserDepartments(null);
				setLoginUserTimezone("system_default");
				return false;
			}

			// Get current token and user data from backend
			const token = KeycloakService.getToken();
			if (!token) {
				console.log("AuthContext: No token from Keycloak, logging out");
				await logout();
				return false;
			}

			const response = await KeycloakService.loginWithBackend(token);
			if (!response.status) {
				console.log("AuthContext: Backend login failed, logging out");
				await logout();
				return false;
			}

			// Check if user changed
			const currentUserId = userMode === "agent" ? user?.staff?.staff_id : user?.id;
			const newUserId = response.mode === "agent" ? response.data.staff.staff_id : response.data.id;

			if (currentUserId !== newUserId) {
				console.log("AuthContext: Keycloak user changed, updating local user");
				handleLoginSuccess(response);
			} else {
				console.log("AuthContext: Keycloak session valid, user unchanged");
			}

			return true;
		} catch (error) {
			console.error("AuthContext: Error checking Keycloak session:", error);
			// On error, assume session invalid and logout
			await logout();
			return false;
		}
	};

	// Load user from localStorage on mount
	useEffect(() => {
		const encodedAuth = localStorage.getItem("auth");

		if (encodedAuth) {
			try {
				const decoded = atob(encodedAuth);
				const data = JSON.parse(decoded);

				if (data.token && isTokenExpired(data.token)) {
					console.log("Token Expired");
					setIsAuthenticated(false);
					setLoading(false);
					setAuthHydrated(true);
					localStorage.removeItem("auth");
					return;
				}

				// Rehydrate all states
				setUser(data.user);
				setUserAccount(data.user?.account || null);
				setUserToken(data.token);
				setUserMode(data.userMode);
				setUserId(data.userId || null);
				setUserName(data.userName || null);
				setUserRole(data.userRole || "user");
				setUserAdditionalData(data.userAdditionalData || null);
				setAuthMethod(data.authMethod || "local");
				setIsAdmin(data.isAdmin || false);
				setIsAgent(data.isAgent || false);
				setIsServiceManager(data.isServiceManager || false);
				setUserDepartments(data.userDepartments || null);
				setUserPermissions(normalizePermissionsPayload(data.userPermissions));

				const restoredTimezone = data?.loginUserTimezone || "system_default";
				setLoginUserTimezone(restoredTimezone);
				// Set timezone in globalConfig immediately for date formatting
				setUserTimezone(restoredTimezone);
				const restoredHidePrices = parseBoolean(data?.shouldHidePrices, false);
				setShouldHidePrices(restoredHidePrices);
				setShouldHidePricesGlobal(restoredHidePrices);
				setLandingPagePreferences(data?.landingPagePreferences || DEFAULT_LANDING_PAGE_PREFERENCES);

				setIsAuthenticated(true);

				// Only validate Keycloak for sessions created via SSO.
				if ((data.authMethod || "local") === "keycloak") {
					checkKeycloakSession().finally(() => {
						setLoading(false);
						setAuthHydrated(true);
					});
				} else {
					setLoading(false);
					setAuthHydrated(true);
				}
			} catch (err) {
				console.error("Failed to decode auth from localStorage:", err);
				localStorage.removeItem("auth"); // cleanup
				setLoading(false);
				setAuthHydrated(true);
			}
		} else {
			setLoading(false);
			setAuthHydrated(true);
		}
	}, []);

